const fetch = require('node-fetch');

let url = 'https://bt-api-int.bouyguestelecom.fr/api/offers?fields=SOME_ARRAY_VALUE&categories=SOME_ARRAY_VALUE&entitlementState=SOME_STRING_VALUE';

let options = {
  method: 'GET',
  headers: {
    'x-kaltura-secret': 'SOME_STRING_VALUE',
    'x-kaltura-api-version': 'SOME_STRING_VALUE',
    'X-Dpps-Trace-idcontracts': 'SOME_STRING_VALUE',
    'x-Dpps-Trace-pfsnocompte': 'SOME_STRING_VALUE',
    'x-request-id': 'SOME_STRING_VALUE',
    'x-source': 'SOME_STRING_VALUE',
    'x-message-id': 'SOME_STRING_VALUE',
    'x-version': 'SOME_STRING_VALUE',
    'If-None-Match': 'SOME_STRING_VALUE',
    'x-dsi-atk-basic': 'SOME_STRING_VALUE',
    'X-User-Agent': 'SOME_STRING_VALUE',
    Authorization: 'Basic REPLACE_BASIC_AUTH'
  }
};

fetch(url, options)
  .then(res => res.json())
  .then(json => console.log(json))
  .catch(err => console.error('error:' + err));

